mapper.sql:
select model.* from (
select satm.id ,satm.api_id ,satm.module_prefix ,COALESCE(satmc.datasource ,satm.datasource) as datasource,satm.table_name,satm.field_config,
satm.tenant_id,satm.create_op,satm.create_time,satm.modify_op,satm.modify_time from security_api_table_model satm
left join security_api_table_model_config satmc on satmc.table_model_id = satm.id
) model


        AND model.api_id = #{param.apiId}


        AND model.module_prefix = #{param.modulePrefix}


        AND model.datasource = #{param.datasource}


        AND model.table_name = #{param.tableName}


        AND model.api_id IN
        #{item}
